-- Create "deleted_refs" table
CREATE TABLE "deleted_refs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "ref" bytea NOT NULL, "tombstoned_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "deleted_refs_ref_width" CHECK (length(ref) = 32));
-- Create index "deletedref_ref" to table: "deleted_refs"
CREATE UNIQUE INDEX "deletedref_ref" ON "deleted_refs" ("ref");
-- Create "pins" table
CREATE TABLE "pins" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "ref" bytea NOT NULL, "target" bytea NOT NULL, "received_at" timestamptz NOT NULL, "deleted_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "pins_ref_width" CHECK (length(ref) = 32), CONSTRAINT "pins_target_width" CHECK (length(target) = 32));
-- Create index "pin_ref" to table: "pins"
CREATE UNIQUE INDEX "pin_ref" ON "pins" ("ref");
-- Create index "pins_target" to table: "pins"
CREATE INDEX "pins_target" ON "pins" ("target") WHERE (deleted_at IS NULL);
-- Create "sessions" table
CREATE TABLE "sessions" ("id" character varying NOT NULL, "agent_id" character varying NOT NULL, "backup_set" character varying NOT NULL, "started_at" timestamptz NOT NULL, "last_seen" timestamptz NOT NULL, "restore_ref" bytea NULL, PRIMARY KEY ("id"));
-- Create "settings" table
CREATE TABLE "settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "policy" character varying NULL, "policy_version" bigint NOT NULL DEFAULT 0, "key_acknowledged_at" timestamptz NULL, "retention_policy" character varying NULL, "hold_days" bigint NOT NULL DEFAULT 14, "trash_days" bigint NOT NULL DEFAULT 14, PRIMARY KEY ("id"));
-- Create "archives" table
CREATE TABLE "archives" ("id" character varying NOT NULL, "state" bigint NOT NULL DEFAULT 0, "session_id" character varying NULL, PRIMARY KEY ("id"), CONSTRAINT "archives_sessions_archives" FOREIGN KEY ("session_id") REFERENCES "sessions" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "archives_session" to table: "archives"
CREATE INDEX "archives_session" ON "archives" ("session_id") WHERE (session_id IS NOT NULL);
-- Create "sets" table
CREATE TABLE "sets" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" character varying NOT NULL, "agent_id" character varying NULL, "state" character varying NOT NULL DEFAULT 'active', "retention_policy" character varying NULL, "retention_paused" boolean NOT NULL DEFAULT false, "erase" boolean NOT NULL DEFAULT false, PRIMARY KEY ("id"));
-- Create index "set_name" to table: "sets"
CREATE UNIQUE INDEX "set_name" ON "sets" ("name");
-- Create "commits" table
CREATE TABLE "commits" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "ref" bytea NOT NULL, "timestamp" timestamptz NOT NULL, "received_at" timestamptz NOT NULL, "tree" bytea NOT NULL, "parent" bytea NULL, "agent_id" character varying NOT NULL DEFAULT '', "scan_start_ns" bigint NOT NULL DEFAULT 0, "policy_version" bigint NOT NULL DEFAULT 0, "consistent" boolean NOT NULL DEFAULT false, "presence" bytea NULL, "partial" boolean NOT NULL DEFAULT false, "retained_by" character varying NOT NULL DEFAULT '', "retire_at" timestamptz NULL, "deleted_at" timestamptz NULL, "expires_at" timestamptz NULL, "tombstoned_at" timestamptz NULL, "logical_size" bigint NULL, "metadata" jsonb NULL, "set_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "commits_sets_set" FOREIGN KEY ("set_id") REFERENCES "sets" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "commits_ref_width" CHECK (length(ref) = 32), CONSTRAINT "commits_tree_width" CHECK (length(tree) = 32));
-- Create index "commitrow_ref" to table: "commits"
CREATE UNIQUE INDEX "commitrow_ref" ON "commits" ("ref");
-- Create index "commitrow_set_id_received_at" to table: "commits"
CREATE INDEX "commitrow_set_id_received_at" ON "commits" ("set_id", "received_at");
-- Create index "commits_expiring" to table: "commits"
CREATE INDEX "commits_expiring" ON "commits" ("expires_at") WHERE ((tombstoned_at IS NULL) AND (expires_at IS NOT NULL));
-- Create index "commits_presence" to table: "commits"
CREATE INDEX "commits_presence" ON "commits" ("set_id") WHERE (presence IS NOT NULL);
-- Create "files" table
CREATE TABLE "files" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "path" character varying NOT NULL, "dir" character varying NOT NULL, "valid_from" timestamptz NOT NULL, "valid_until" timestamptz NULL, "ref" bytea NOT NULL, "mtime_ns" bigint NOT NULL, "mode" bigint NOT NULL, "user" character varying NOT NULL, "group" character varying NOT NULL, "size" bigint NOT NULL, "set_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "files_sets_files" FOREIGN KEY ("set_id") REFERENCES "sets" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "files_ref_width" CHECK (length(ref) = 32));
-- Create index "file_set_id_path_valid_from" to table: "files"
CREATE UNIQUE INDEX "file_set_id_path_valid_from" ON "files" ("set_id", "path", "valid_from");
-- Create index "files_open" to table: "files"
CREATE INDEX "files_open" ON "files" ("set_id", "dir") WHERE (valid_until IS NULL);
-- Create "objects" table
CREATE TABLE "objects" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "ref" bytea NOT NULL, "start" bigint NOT NULL, "length" bigint NOT NULL, "type" bigint NOT NULL, "archive_id" character varying NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "objects_archives_objects" FOREIGN KEY ("archive_id") REFERENCES "archives" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "objects_ref_width" CHECK (length(ref) = 32));
-- Create index "object_ref_archive_id" to table: "objects"
CREATE UNIQUE INDEX "object_ref_archive_id" ON "objects" ("ref", "archive_id");
-- Create "set_refs" table
CREATE TABLE "set_refs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "ref" bytea NOT NULL, "set_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "set_refs_sets_refs" FOREIGN KEY ("set_id") REFERENCES "sets" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "set_refs_ref_width" CHECK (length(ref) = 32));
-- Create index "setref_ref" to table: "set_refs"
CREATE INDEX "setref_ref" ON "set_refs" ("ref");
-- Create index "setref_set_id_ref" to table: "set_refs"
CREATE UNIQUE INDEX "setref_set_id_ref" ON "set_refs" ("set_id", "ref");
-- Create "trees" table
CREATE TABLE "trees" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "path" character varying NOT NULL, "dir" character varying NOT NULL, "valid_from" timestamptz NOT NULL, "valid_until" timestamptz NULL, "ref" bytea NOT NULL, "set_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "trees_sets_trees" FOREIGN KEY ("set_id") REFERENCES "sets" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "trees_ref_width" CHECK (length(ref) = 32));
-- Create index "tree_set_id_path_valid_from" to table: "trees"
CREATE UNIQUE INDEX "tree_set_id_path_valid_from" ON "trees" ("set_id", "path", "valid_from");
-- Create index "trees_open" to table: "trees"
CREATE INDEX "trees_open" ON "trees" ("set_id", "dir") WHERE (valid_until IS NULL);
